g=[[3,7,9,6],[3,3,0,4],[3,3,3,6],[3,5,8,3]]
n=len(g)
out=[[0]*(2*n) for _ in range(2*n)]
rots={ (0,0):g, (0,1):[list(row) for row in zip(*g[::-1])], (1,0):[list(row) for row in zip(*g)][::-1], (1,1):[row[::-1] for row in g[::-1]] }
for (br,bc),a in rots.items():
 for i in range(n):
  for j in range(n): out[br*n+i][bc*n+j]=a[i][j]
print(out)
print([len(r) for r in out])
